<template>
  <router-view v-if="$route.meta.public" />
  <div v-else class="admin-shell" :class="{collapsed,'drawer-open':drawerOpen}">
    <button v-if="drawerOpen" class="drawer-backdrop" aria-label="Đóng menu" @click="drawerOpen=false"></button>
    <aside class="admin-nav" aria-label="Điều hướng quản trị">
      <div class="brand-row"><RouterLink class="brand" to="/author-applications" title="NoVi quản trị"><span class="brand-mark">N</span><span class="nav-label">NoVi <small>Quản trị</small></span></RouterLink><button class="icon-button desktop-collapse" :title="collapsed?'Mở rộng menu':'Thu gọn menu'" @click="toggleCollapse">{{collapsed?'›':'‹'}}</button><button class="icon-button mobile-close" title="Đóng menu" @click="drawerOpen=false">×</button></div>
      <nav><RouterLink v-for="item in navItems" :key="item.to" :to="item.to" :title="collapsed?item.label:undefined" @click="drawerOpen=false"><span class="nav-icon" aria-hidden="true">{{item.icon}}</span><span class="nav-label">{{item.label}}</span></RouterLink></nav>
      <div class="sidebar-foot nav-label">NoVi Admin · 2026</div>
    </aside>
    <div class="admin-workspace"><header class="topbar"><div class="topbar-title"><button class="icon-button mobile-menu" aria-label="Mở menu" @click="drawerOpen=true">☰</button><div><small>Quản trị NoVi</small><h1>{{pageTitle}}</h1></div></div><div class="topbar-actions"><button class="icon-button" :aria-label="theme==='dark'?'Chuyển sang giao diện sáng':'Chuyển sang giao diện tối'" :title="theme==='dark'?'Giao diện sáng':'Giao diện tối'" @click="toggleTheme">{{theme==='dark'?'☀':'☾'}}</button><div class="account-menu"><button class="account-trigger" :aria-expanded="accountOpen" @click="accountOpen=!accountOpen"><span class="avatar">{{initials}}</span><span class="account-copy"><strong>{{session?.user?.fullName||'Quản trị viên'}}</strong><small>{{session?.user?.email}}</small></span><span>⌄</span></button><div v-if="accountOpen" class="account-dropdown" role="menu"><div class="dropdown-user"><strong>{{session?.user?.fullName}}</strong><small>{{session?.user?.email}}</small></div><button role="menuitem" @click="logout">Đăng xuất</button></div></div></div></header><main class="admin-content"><router-view /></main></div>
  </div>
</template>
<script setup>
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {adminSession} from './services/adminSession'
const route=useRoute(),router=useRouter(),session=computed(()=>adminSession.get());const navItems=[{to:'/author-applications',label:'Yêu cầu tác giả',icon:'✎'},{to:'/moderation',label:'Kiểm duyệt nội dung',icon:'✓'},{to:'/novels',label:'Quản lý truyện',icon:'▤'},{to:'/users',label:'Người dùng',icon:'♙'},{to:'/categories',label:'Thể loại',icon:'▦'},{to:'/content-reports',label:'Báo cáo nội dung',icon:'⚑'}];const pageTitle=computed(()=>route.meta.title||navItems.find(x=>x.to===route.path)?.label||'Quản trị');const collapsed=ref(localStorage.getItem('novi-admin-sidebar')==='collapsed'),drawerOpen=ref(false),accountOpen=ref(false),theme=ref(localStorage.getItem('novi-admin-theme')||'light');const initials=computed(()=>{const value=session.value?.user?.fullName||session.value?.user?.email||'NV';return value.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()});function applyTheme(){document.documentElement.dataset.theme=theme.value;localStorage.setItem('novi-admin-theme',theme.value)}function toggleTheme(){theme.value=theme.value==='dark'?'light':'dark';applyTheme()}function toggleCollapse(){collapsed.value=!collapsed.value;localStorage.setItem('novi-admin-sidebar',collapsed.value?'collapsed':'expanded')}function logout(){accountOpen.value=false;adminSession.clear();router.replace('/login')}function onKey(event){if(event.key==='Escape'){drawerOpen.value=false;accountOpen.value=false}}watch(()=>route.fullPath,()=>{drawerOpen.value=false;accountOpen.value=false});onMounted(()=>{applyTheme();document.addEventListener('keydown',onKey)});onBeforeUnmount(()=>document.removeEventListener('keydown',onKey))
</script>
<style src="./assets/admin.css"></style>
